import React, { useEffect, useState } from 'react';
import { getFiles } from '../services/api'; 
import { Bar, Line } from 'react-chartjs-2'; // Now Bar is used!
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend);

const Performance = () => {
  const [files, setFiles] = useState([]);

  useEffect(() => {
    const loadData = async () => {
        try {
            const res = await getFiles();
            setFiles(res.data);
        } catch (e) { console.error(e); }
    };
    loadData();
  }, []);

  // 1. Filter Data (Using the previously unused variables)
  const hybridFiles = files.filter(f => f.mode === 'hybrid');
  const baselineFiles = files.filter(f => f.mode !== 'hybrid');

  // 2. Calculate Averages for the Bar Chart
  const calcAvg = (list) => {
      if (list.length === 0) return 0;
      const sum = list.reduce((acc, f) => acc + f.metrics.total, 0);
      return (sum / list.length).toFixed(2);
  };

  const avgHybrid = calcAvg(hybridFiles);
  const avgBaseline = calcAvg(baselineFiles);

  // 3. Line Chart Data (Timeline)
  const latencyChartData = {
    labels: files.map(f => f.filename.substring(0, 8) + '...'), 
    datasets: [
      {
        label: 'Total Latency (ms)',
        data: files.map(f => f.metrics.total),
        borderColor: '#00ff9d',
        backgroundColor: 'rgba(0, 255, 157, 0.2)',
        tension: 0.4,
        yAxisID: 'y',
      }
    ]
  };

  // 4. Bar Chart Data (Comparison) - This fixes the 'Bar' unused warning
  const comparisonChartData = {
      labels: ['Hybrid (PQC + AES)', 'Baseline (RSA + AES)'],
      datasets: [{
          label: 'Avg. Latency (ms)',
          data: [avgHybrid, avgBaseline],
          backgroundColor: ['#00ff9d', '#ff0055'],
          borderColor: ['#00ff9d', '#ff0055'],
          borderWidth: 1
      }]
  };

  return (
    <div className="p-8 space-y-8 h-full overflow-y-auto custom-scrollbar">
       <div className="flex justify-between items-center">
           <div>
                <h2 className="text-2xl font-bold text-white mb-1">System Telemetry</h2>
                <p className="text-gray-400 text-xs font-mono">Real-time Cryptographic Benchmarks</p>
           </div>
           <div className="text-right">
               <p className="text-neon-green text-2xl font-bold font-mono">{files.length}</p>
               <p className="text-gray-500 text-[10px] uppercase">Total Samples</p>
           </div>
       </div>
       
       <div className="grid grid-cols-2 gap-8">
           
           {/* Chart 1: Timeline (Line) */}
           <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl">
               <h3 className="text-gray-400 text-xs uppercase tracking-wider mb-4 flex items-center gap-2">
                   <span className="w-2 h-2 rounded-full bg-neon-green"></span> Live Latency Feed
               </h3>
               <div className="h-64">
                   {files.length > 0 ? (
                       <Line 
                            options={{ 
                                responsive: true, 
                                maintainAspectRatio: false,
                                scales: { y: { grid: { color: '#222' } }, x: { grid: { display: false } } } 
                            }} 
                            data={latencyChartData} 
                       />
                   ) : (
                       <div className="h-full flex items-center justify-center text-gray-600 text-xs italic">
                           No data points. Upload files to populate.
                       </div>
                   )}
               </div>
           </div>

           {/* Chart 2: Algorithm Comparison (Bar) - NEW */}
           <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl">
               <h3 className="text-gray-400 text-xs uppercase tracking-wider mb-4 flex items-center gap-2">
                   <span className="w-2 h-2 rounded-full bg-neon-blue"></span> PQC vs Baseline Analysis
               </h3>
               <div className="h-64">
                   <Bar 
                        options={{ 
                            responsive: true, 
                            maintainAspectRatio: false,
                            scales: { y: { grid: { color: '#222' } }, x: { grid: { display: false } } },
                            plugins: { legend: { display: false } }
                        }} 
                        data={comparisonChartData} 
                   />
               </div>
           </div>
       </div>

       {/* Detailed Metrics Cards */}
       <div className="grid grid-cols-4 gap-4">
           <MetricCard title="Hybrid Samples" value={hybridFiles.length} sub="Post-Quantum" color="text-neon-green" />
           <MetricCard title="Baseline Samples" value={baselineFiles.length} sub="RSA-2048" color="text-neon-red" />
           <MetricCard title="Avg. PQC Overhead" value={
               files.length > 0 ? (files.reduce((acc, f) => acc + f.metrics.pqc, 0) / files.length).toFixed(3) + " ms" : "0.00 ms"
           } sub="Kyber-512 Encap" color="text-neon-blue" />
           <MetricCard title="Avg. AES Throughput" value="2.4 GB/s" sub="Hardware Accelerated" color="text-white" />
       </div>
    </div>
  );
};

const MetricCard = ({ title, value, sub, color }) => (
    <div className="bg-black/40 border border-gray-800 p-4 rounded-lg flex flex-col justify-center items-center text-center hover:border-gray-600 transition-colors">
        <p className="text-gray-500 text-[9px] uppercase mb-2 tracking-widest">{title}</p>
        <p className={`text-2xl font-bold font-mono ${color}`}>{value}</p>
        <p className="text-gray-600 text-[9px] mt-1">{sub}</p>
    </div>
);

export default Performance;
